<?php
namespace Alprof\Core; use PDO;
final class Auth { public function __construct(private PDO $db){} public function attempt(string $email,string $password): bool {$q=$this->db->prepare('SELECT id,name,email,password_hash,role,status FROM users WHERE email=? LIMIT 1');$q->execute([mb_strtolower(trim($email))]);$u=$q->fetch();if(!$u||$u['status']!=='active'||!password_verify($password,$u['password_hash'])){$this->audit(null,'login_failed',['email'=>$email]);usleep(250000);return false;}session_regenerate_id(true);unset($u['password_hash']);$_SESSION['user']=$u;$_SESSION['last_activity']=time();$this->audit((int)$u['id'],'login_success');return true;} public function check():bool{return isset($_SESSION['user'])&&time()-($_SESSION['last_activity']??0)<(int)envv('SESSION_LIFETIME','7200');} public function user():?array{return $this->check()?$_SESSION['user']:null;} public function requireAuth():void{if(!$this->check()){$_SESSION=[];header('Location: /');exit;}$_SESSION['last_activity']=time();} public function isManager():bool{return ($this->user()['role']??'')==='manager';} public function logout():void{$this->audit((int)($_SESSION['user']['id']??0),'logout');$_SESSION=[];if(ini_get('session.use_cookies')){$p=session_get_cookie_params();setcookie(session_name(),'',time()-42000,$p['path'],$p['domain'],(bool)$p['secure'],(bool)$p['httponly']);}session_destroy();} public function can(string $permission):bool{if($this->isManager())return true;$q=$this->db->prepare('SELECT 1 FROM user_permissions up JOIN permissions p ON p.id=up.permission_id WHERE up.user_id=? AND p.code=?');$q->execute([$this->user()['id']??0,$permission]);return(bool)$q->fetchColumn();} public function audit(?int $uid,string $action,array $meta=[]):void{try{$q=$this->db->prepare('INSERT INTO audit_logs(user_id,action,ip,metadata,created_at) VALUES(?,?,?,?,NOW())');$q->execute([$uid?:null,$action,$_SERVER['REMOTE_ADDR']??'cli',json_encode($meta,JSON_UNESCAPED_UNICODE)]);}catch(\Throwable){}}}
